contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address log1, address log2) public {
        bool firstReverted;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        require(!firstReverted, "first SetLogFile must succeed on fresh contract");

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetLogFile(log2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }
        assert(!firstReverted && secondReverted);
    }
}

